private long bindAt(int type,Pointer pointer,MachOModule targetImage,String symbolName,boolean withDependencies){
  Symbol symbol=null;
  try {
    symbol=targetImage.findSymbolByName(symbolName,withDependencies);
  } catch (RuntimeException e) {
    // treat as symbol not found
  }
  if (symbol == null) {
    long bindAt=0;
    for (    HookListener listener : hookListeners) {
      long hook=listener.hook(emulator.getSvcMemory(),this.name,symbolName,HookListener.WEAK_BIND);
      if (hook > 0) {
        bindAt=hook;
        break;
      }
    }
    if (bindAt > 0) {
      Pointer newPointer=UnidbgPointer.pointer(emulator,bindAt);
      switch (type) {
        case BIND_TYPE_POINTER: pointer.setPointer(0,newPointer); break;
        case BIND_TYPE_TEXT_ABSOLUTE32: case BIND_TYPE_TEXT_PCREL32: default: throw new IllegalStateException("bad bind type " + type);
      }
      return bindAt;
    }
    if (withDependencies) {
      log.info("bindAt type=" + type + ", symbolName="+ symbolName+ ", upwardLibraries="+ this.upwardLibraries.values()+ ", module="+ this.name+ ", targetImage="+ targetImage);
    }
    return 0;
  }
  long bindAt=symbol.getAddress();
  for (HookListener listener : hookListeners) {
    long hook=listener.hook(emulator.getSvcMemory(),symbol.getModuleName(),symbol.getName(),bindAt);
    if (hook > 0) {
      bindAt=hook;
      break;
    }
  }
  if (log.isTraceEnabled()) {
    log.trace("bindAt 0x=" + Long.toHexString(symbol.getValue()) + ", type="+ type+ ", symbolName="+ symbol.getModuleName()+ ", symbol="+ symbol+ ", pointer="+ pointer+ ", bindAt=0x"+ Long.toHexString(bindAt));
  }
  switch (type) {
    case BIND_TYPE_POINTER: Pointer newPointer=UnidbgPointer.pointer(emulator,bindAt); pointer.setPointer(0,newPointer); break;
    case BIND_TYPE_TEXT_ABSOLUTE32: pointer.setInt(0,(int)(bindAt)); break;
    case BIND_TYPE_TEXT_PCREL32: default: throw new IllegalStateException("bad bind type " + type);
  }
  return bindAt;
}
